def _parse_expected_findings(
    raw: list[dict], entry_name: str
) -> list[ExpectedFinding]:
    """Validate and build ExpectedFinding list from manifest YAML.

    Strict on shape (a malformed answer key would silently poison the
    findings scoring): file must be a non-empty string, description a
    non-empty string, line_range absent or a two-int list.
    """
    findings: list[ExpectedFinding] = []
    if not isinstance(raw, list):
        raise ValueError(
            "expected_findings in %r must be a list" % entry_name
        )
    for item in raw:
        if not isinstance(item, dict):
            raise ValueError(
                "expected_findings entry in %r is not a mapping"
                % entry_name
            )
        file = item.get("file")
        description = item.get("description")
        if not isinstance(file, str) or not file:
            raise ValueError(
                "expected_findings entry in %r missing file" % entry_name
            )
        if not isinstance(description, str) or not description:
            raise ValueError(
                "expected_findings entry in %r missing description"
                % entry_name
            )
        line_range = None
        raw_range = item.get("line_range")
        if raw_range is not None:
            if (
                not isinstance(raw_range, list)
                or len(raw_range) != 2
                or not all(
                    isinstance(v, int) and not isinstance(v, bool)
                    for v in raw_range
                )
                or raw_range[0] < 1
                or raw_range[1] < raw_range[0]
            ):
                raise ValueError(
                    "expected_findings entry in %r has invalid "
                    "line_range %r" % (entry_name, raw_range)
                )
            line_range = (raw_range[0], raw_range[1])
        findings.append(
            ExpectedFinding(
                file=file,
                description=description,
                line_range=line_range,
            )
        )
    return findings

def _read_confirmed_findings(temp_dir: str) -> list[dict]:
    """CONFIRMED findings from the run's state.json.

    Returns a list of {file, line_range, description} dicts. Empty list
    if the file is absent or malformed. Called BEFORE temp dir cleanup
    in the per-run loop, mirroring _read_advisory_findings.
    """
    state_path = Path(temp_dir) / ".code-forge" / "state.json"
    if not state_path.exists():
        return []
    try:
        data = json.loads(state_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return []
    if not isinstance(data, dict):
        return []
    raw_findings = data.get("findings")
    if not isinstance(raw_findings, list):
        return []
    confirmed = []
    for f in raw_findings:
        if not isinstance(f, dict):
            continue
        if f.get("disposition") != "CONFIRMED":
            continue
        raw_range = f.get("line_range")
        line_range = None
        if (
            isinstance(raw_range, list)
            and len(raw_range) == 2
            and all(
                isinstance(v, int) and not isinstance(v, bool)
                for v in raw_range
            )
        ):
            line_range = raw_range
        description = f.get("description")
        confirmed.append({
            "file": f.get("file") or "",
            "line_range": line_range,
            "description": description if isinstance(
                description, str
            ) else "",
        })
    return confirmed

def _score_findings(
    entry: CorpusEntry, confirmed: list[dict]
) -> tuple[int, int, int]:
    """(hits, misses, fps) for one run against the entry's answer key.

    A hit requires an actual CONFIRMED finding matching an expected
    finding via finding_hit. An actual finding matching no expected
    finding counts as a false positive. Entries without an answer key
    score (0, 0, 0).
    """
    expected = entry.expected_findings
    if not expected:
        return (0, 0, 0)
    hits = sum(
        1 for e in expected
        if any(finding_hit(a, e) for a in confirmed)
    )
    fps = sum(
        1 for a in confirmed
        if not any(finding_hit(a, e) for e in expected)
    )
    return (hits, len(expected) - hits, fps)


